def choose_move(observation):
    env = observation.get("environment_name", "resource_collection")
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))

    # Defensive helpers
    def step_toward(tx, ty, cx, cy):
        dx = 0 if tx == cx else (1 if tx > cx else -1)
        dy = 0 if ty == cy else (1 if ty > cy else -1)
        return [dx, dy]

    # Pursuit-Evasion
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(ox, oy, sx, sy)
        # Evader logic: move toward farthest corner to maximize distance
        w = observation.get("grid_width", 1)
        h = observation.get("grid_height", 1)
        corners = [
            [0, 0],
            [0, max(0, h - 1)],
            [max(0, w - 1), 0],
            [max(0, w - 1), max(0, h - 1)],
        ]
        # pick corner farthest from opponent (robust if opponent missing)
        try:
            target = max(corners, key=lambda p: abs(p[0] - ox) + abs(p[1] - oy))
        except Exception:
            target = corners[0]
        return step_toward(target[0], target[1], sx, sy)

    # Territory control
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("owned_or_unclaimed_cells") or []
        if not targets:
            return [0, 0]
        best = min(targets, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return step_toward(best[0], best[1], sx, sy)

    # Resource collection
    resources = observation.get("resources") or []
    if resources:
        best = min(resources, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return step_toward(best[0], best[1], sx, sy)

    # Fallback: move toward opponent to maintain engagement
    return step_toward(ox, oy, sx, sy)

